export const abilityTable = pgTable("ability", {
  "active": boolean("active").notNull(),
  "companyId": text("companyId").references(() => companyTable["id"]).notNull(),
  "createdAt": timestamp("createdAt", { withTimezone: true, mode: "string" }).notNull(),
  "createdBy": text("createdBy").references(() => userTable["id"]).notNull(),
  "curve": jsonb("curve").notNull(),
  "id": text("id").primaryKey(),
  "name": text("name").notNull(),
  "shadowWeeks": numeric("shadowWeeks", { mode: "number" }).notNull(),
  "updatedAt": timestamp("updatedAt", { withTimezone: true, mode: "string" }),
  "updatedBy": text("updatedBy").references(() => userTable["id"]),
}, (t) => [
  pgPolicy("ability_tenant_select", {
    as: "permissive",
    for: "select",
    to: "carbon_app",
    using: sql`${t["companyId"]} = ANY(app_companies_for_context())`,
  }),
  pgPolicy("ability_tenant_insert", {
    as: "permissive",
    for: "insert",
    to: "carbon_app",
    withCheck: sql`${t["companyId"]} = ANY(app_companies_for_context())`,
  }),
  pgPolicy("ability_tenant_update", {
    as: "permissive",
    for: "update",
    to: "carbon_app",
    using: sql`${t["companyId"]} = ANY(app_companies_for_context())`,
    withCheck: sql`${t["companyId"]} = ANY(app_companies_for_context())`,
  }),
  pgPolicy("ability_tenant_delete", {
    as: "permissive",
    for: "delete",
    to: "carbon_app",
    using: sql`${t["companyId"]} = ANY(app_companies_for_context())`,
  }),
]).enableRLS();
